A debounce function is used to delay the execution of an event handler until a certain amount of time has passed since the last event. This is useful for preventing rapid-fire events from overwhelming the system or causing unwanted side effects. Here's an example of a debounce function written in JavaScript:

    function debounce(handler, wait) {
      let timeout;

      return function() {
        clearTimeout(timeout);
        timeout = setTimeout(() => {
          handler.apply(this, arguments);
        }, wait);
      };
    }

    // Example usage:
    document.getElementById('input').addEventListener('input', debounce(() => {
      console.log('Input changed:', document.getElementById('input').value);
    }, 300));


